const { withXcodeProject } = require('@expo/config-plugins');

/**
 * Keeps the generated Xcode project in sync with app.config.js.
 *
 * `ios/` is gitignored and fully regenerated by `expo prebuild --clean`, which
 * means anything hand-edited in Xcode is silently destroyed on the next
 * prebuild. Two things were being lost that way:
 *
 *   1. Version/build. Expo writes version + ios.buildNumber into Info.plist
 *      but never into the MARKETING_VERSION / CURRENT_PROJECT_VERSION build
 *      settings, which is what Xcode's General tab displays. That mismatch
 *      made the UI read 1.0 / 1 while the binary shipped the right numbers.
 *
 *   2. Signing. DevelopmentTeam and ProvisioningStyle were added by hand to
 *      the target attributes so the CLI archive/export could sign. A prebuild
 *      wiped them, and the next release would fail to sign for non-obvious
 *      reasons.
 *
 * This plugin writes all four on every prebuild, so the Xcode UI, the shipped
 * binary, and the signing setup always match app.config.js.
 */
const DEVELOPMENT_TEAM = '45B5NQR2B7'; // Axiom 38 LLC

module.exports = function withXcodeProjectSync(config) {
  return withXcodeProject(config, (cfg) => {
    const project = cfg.modResults;
    const version = cfg.version || '1.0.0';
    const build = (cfg.ios && cfg.ios.buildNumber) || '1';

    // ── Version + build number on every app-target configuration ──
    const configurations = project.pbxXCBuildConfigurationSection();
    for (const key of Object.keys(configurations)) {
      const entry = configurations[key];
      if (typeof entry !== 'object' || !entry.buildSettings) continue;
      const bs = entry.buildSettings;
      // PRODUCT_NAME is only present on real app/extension targets, not on
      // the project-level or Pods configurations.
      if (bs.PRODUCT_NAME === undefined) continue;
      bs.MARKETING_VERSION = version;
      bs.CURRENT_PROJECT_VERSION = build;
      bs.DEVELOPMENT_TEAM = DEVELOPMENT_TEAM;
    }

    // ── Signing attributes on the native target ──
    // Xcode automatic signing fails for this team in the GUI (no registered
    // devices), so releases are built via CLI archive + exportArchive with
    // -allowProvisioningUpdates. That path still needs these attributes.
    const projectSection = project.pbxProjectSection();
    for (const key of Object.keys(projectSection)) {
      const proj = projectSection[key];
      if (typeof proj !== 'object' || !proj.attributes) continue;
      const targetAttributes = proj.attributes.TargetAttributes;
      if (!targetAttributes) continue;
      for (const targetKey of Object.keys(targetAttributes)) {
        const attrs = targetAttributes[targetKey];
        if (typeof attrs !== 'object') continue;
        attrs.DevelopmentTeam = DEVELOPMENT_TEAM;
        attrs.ProvisioningStyle = 'Automatic';
      }
    }

    return cfg;
  });
};
